CREATE TABLE IF NOT EXISTS `authRateLimits` (`keyHash` CHAR(64) NOT NULL,`scope` VARCHAR(32) NOT NULL,`count` INT UNSIGNED NOT NULL DEFAULT 1,`resetAt` DATETIME(3) NOT NULL,`updatedAt` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) ON UPDATE CURRENT_TIMESTAMP(3),PRIMARY KEY (`keyHash`),KEY `auth_rate_limits_reset_idx` (`resetAt`)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
